    /**
     * @return list<string>
     */
    public static function names(): array
    {
        return array_keys(self::PATHS);
    }

    public static function has(string $name): bool
    {
        return isset(self::PATHS[$name]);
    }

    /**
     * Inline SVG, or an empty string when the name is unknown.
     */
    public static function svg(string $name, string $size = 'md'): string
    {
        if (! isset(self::PATHS[$name])) {
            return '';
        }

        $px = match ($size) {
            'sm' => 16,
            'lg' => 24,
            'xl' => 32,
            default => 20,
        };

        return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="'.$px.'" height="'.$px.'" fill="currentColor" aria-hidden="true" focusable="false">'.self::PATHS[$name].'</svg>';
    }
}
